def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    count = len(values)
    average = sum(values) / count
    return {
        "value": average,
        "trace": {
            "values": values,
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
